from pathlib import Path
import json,sqlite3,time,sys
home=Path.home()
unitdir=home/".config/systemd/user"
root=home/".local/share/prediction-project-executor/campaigns/FULL-A2Z-LIVE-20261004-V4"
task_id="A2Z-V4-SOL-BUILD-20261007-R4"
out={"now":time.time(),"units":[]}
if unitdir.exists():
    for p in sorted(unitdir.glob("prediction-*")):
        if "a2z-v4" in p.name or "codex-supervisor" in p.name:
            item={"name":p.name,"is_symlink":p.is_symlink()}
            try:item["target"]=str(p.resolve())
            except Exception:pass
            try:item["content"]=p.read_text(errors="replace")[:12000]
            except Exception as e:item["read_error"]=type(e).__name__+":"+str(e)
            out["units"].append(item)
dbp=root/"models/runtime.sqlite"
if dbp.exists():
    db=sqlite3.connect("file:"+str(dbp)+"?mode=ro",uri=True)
    try:
        row=db.execute("select status,attempt,run,thread from tasks where id=?",(task_id,)).fetchone()
        tr=db.execute("select state,reason,attempt,checkpoint,next_action,stamp,retry from transitions where task=? order by seq desc limit 1",(task_id,)).fetchone()
    finally:db.close()
    out["task"]=row
    out["transition"]=tr
    if tr:
        out["retry_delta"]=float(tr[6] or 0)-float(tr[5] or 0)
        out["retry_overdue_seconds"]=max(0,int(time.time()-float(tr[6] or 0)))
print("E130_SCHEDULER "+json.dumps(out,separators=(",",":"),default=str),flush=True)
raise SystemExit(0)
